import Foundation
import Testing
@testable import SlumpyKit // module that defines DailyProgress and ReadingSession

@Suite("DailyProgress.minutesToday")
struct DailyProgressTests {
    /// Fixed zone without DST, so results don't depend on the machine running the tests.
    static let moscow: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "Europe/Moscow")!
        return calendar
    }()

    static let utc: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = .gmt
        return calendar
    }()

    /// A moment in October 2026 in the given calendar's time zone.
    static func date(
        day: Int, hour: Int, minute: Int = 0, second: Int = 0, in calendar: Calendar = moscow
    ) throws -> Date {
        let components = DateComponents(
            year: 2026, month: 10, day: day, hour: hour, minute: minute, second: second
        )
        return try #require(calendar.date(from: components))
    }

    static func session(
        day: Int, hour: Int, minute: Int = 0, second: Int = 0, seconds: TimeInterval
    ) throws -> ReadingSession {
        ReadingSession(
            startedAt: try date(day: day, hour: hour, minute: minute, second: second),
            duration: seconds
        )
    }

    let now: Date

    init() throws {
        now = try Self.date(day: 27, hour: 12)
    }

    private func minutes(_ sessions: [ReadingSession], calendar: Calendar = moscow) -> Int {
        DailyProgress.minutesToday(sessions, now: now, calendar: calendar)
    }

    // MARK: - Basics

    @Test("No sessions gives zero")
    func emptyInput() {
        #expect(minutes([]) == 0)
    }

    @Test("A single session today is counted in whole minutes")
    func singleSessionToday() throws {
        let sessions = [try Self.session(day: 27, hour: 9, seconds: 25 * 60)]
        #expect(minutes(sessions) == 25)
    }

    @Test("All of today's sessions are summed")
    func sumsTodaySessions() throws {
        let sessions = [
            try Self.session(day: 27, hour: 8, seconds: 10 * 60),
            try Self.session(day: 27, hour: 9, minute: 30, seconds: 15 * 60),
            try Self.session(day: 27, hour: 11, seconds: 5 * 60),
        ]
        #expect(minutes(sessions) == 30)
    }

    @Test("Sessions from other days are ignored")
    func ignoresOtherDays() throws {
        let sessions = [
            try Self.session(day: 26, hour: 12, seconds: 20 * 60), // yesterday, same time
            try Self.session(day: 28, hour: 12, seconds: 20 * 60), // tomorrow
            try Self.session(day: 20, hour: 12, seconds: 20 * 60), // a week ago
            try Self.session(day: 27, hour: 10, seconds: 7 * 60),
        ]
        #expect(minutes(sessions) == 7)
    }

    // MARK: - Day boundaries

    @Test("Midnight boundaries: last second of yesterday out, first and last second of today in")
    func dayBoundaries() throws {
        let sessions = [
            try Self.session(day: 26, hour: 23, minute: 59, second: 59, seconds: 60 * 60),
            try Self.session(day: 27, hour: 0, seconds: 2 * 60),
            try Self.session(day: 27, hour: 23, minute: 59, second: 59, seconds: 3 * 60),
        ]
        #expect(minutes(sessions) == 5)
    }

    @Test("A session crossing midnight belongs entirely to the day it started")
    func crossingMidnightCountsByStart() throws {
        // Started yesterday at 23:50 and ran 30 minutes, 20 of them today.
        let sessions = [try Self.session(day: 26, hour: 23, minute: 50, seconds: 30 * 60)]
        #expect(minutes(sessions) == 0)
    }

    // MARK: - Rounding

    @Test(
        "Total seconds are truncated down to whole minutes",
        arguments: zip(
            [0, 1, 59, 60, 61, 119, 120, 3599, 3600] as [TimeInterval],
            [0, 0, 0, 1, 1, 1, 2, 59, 60]
        )
    )
    func truncatesToWholeMinutes(seconds: TimeInterval, expected: Int) throws {
        let sessions = [try Self.session(day: 27, hour: 9, seconds: seconds)]
        #expect(minutes(sessions) == expected)
    }

    @Test("Seconds are summed before truncation, not per session")
    func sumsBeforeTruncating() throws {
        let sessions = [
            try Self.session(day: 27, hour: 8, seconds: 40),
            try Self.session(day: 27, hour: 9, seconds: 40),
            try Self.session(day: 27, hour: 10, seconds: 40),
        ]
        // 120 s → 2 min; truncating each session first would give 0.
        #expect(minutes(sessions) == 2)
    }

    // MARK: - Calendar

    @Test("\"Today\" is decided by the injected calendar's time zone")
    func usesCalendarTimeZone() throws {
        // 01:00 on the 27th in Moscow is 22:00 on the 26th in UTC.
        let sessions = [try Self.session(day: 27, hour: 1, seconds: 20 * 60)]

        #expect(minutes(sessions, calendar: Self.moscow) == 20)
        #expect(minutes(sessions, calendar: Self.utc) == 0)
    }
}
